// ---- Aviso de llamadas: arma la lista de cuentas en Estado=llamar_manual ----
const L='https://raw.githubusercontent.com/sanrotech369-dot/acces-assets/main/';
const hoy=$now.toFormat('yyyy-LL-dd');
const rows=$input.all().map(i=>i.json).filter(r=>r && r.ID_Lead && String(r.Estado)==='llamar_manual');
if(!rows.length) return [];   // si no hay nada que llamar, no manda correo
// ordenar por Pre_Score desc
rows.sort((a,b)=>(Number(b.Pre_Score)||0)-(Number(a.Pre_Score)||0));
const esc=s=>String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const filas=rows.map((r,i)=>{
  const tel=esc(r.Telefono||'—');
  const ciu=esc([r.Ciudad,r.Estado_Region].filter(Boolean).join(', ')||'—');
  const gan=esc(r.Gancho||r.Trigger_Regulatorio||'');
  return '<tr style="border-bottom:1px solid #eee;">'
    +'<td style="padding:8px 10px;color:#888;">'+(i+1)+'</td>'
    +'<td style="padding:8px 10px;"><strong>'+esc(r.Empresa)+'</strong><br><span style="color:#888;font-size:12px;">'+esc(r.Sector||'')+'</span></td>'
    +'<td style="padding:8px 10px;font-size:15px;color:#0a3d62;"><strong>'+tel+'</strong></td>'
    +'<td style="padding:8px 10px;">'+ciu+'</td>'
    +'<td style="padding:8px 10px;color:#555;font-size:13px;">'+gan+'</td>'
    +'</tr>';
}).join('');
const html='<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;color:#222;max-width:820px;">'
  +'<p style="margin:0 0 16px 0;"><img src="'+L+'logo.png" alt="ACCES GROUP" style="max-width:200px;height:auto;"></p>'
  +'<h2 style="margin:0 0 4px 0;color:#0a3d62;">&#128222; Cuentas para llamar hoy</h2>'
  +'<p style="margin:0 0 16px 0;color:#666;">ATENEA detect&oacute; <strong>'+rows.length+'</strong> cuenta(s) sin correo v&aacute;lido pero con tel&eacute;fono. Vale la pena marcarles &mdash; ya est&aacute;n calificadas.</p>'
  +'<table cellpadding="0" cellspacing="0" style="width:100%;border-collapse:collapse;border-top:2px solid #0a3d62;">'
  +'<tr style="background:#f4f6f8;text-align:left;font-size:12px;color:#555;">'
  +'<th style="padding:8px 10px;">#</th><th style="padding:8px 10px;">Empresa</th><th style="padding:8px 10px;">Tel&eacute;fono</th><th style="padding:8px 10px;">Ciudad</th><th style="padding:8px 10px;">Gancho para abrir</th></tr>'
  +filas
  +'</table>'
  +'<p style="margin:18px 0 0 0;color:#888;font-size:12px;">Cuando llames a una y cambies su Estado en el CRM, se cae sola de esta lista. &mdash; ATENEA &middot; Agente de prospecci&oacute;n ACCES GROUP</p>'
  +'</div>';
return [{json:{reporte_html:html, total:rows.length, hoy}}];
